import pandas as pd, statsmodels.api as sm
D=pd.read_csv('data/explore.csv'); xs=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm'];
for x in xs:
 z=D[['species_richness',x,'region']].dropna(); s=pd.get_dummies(z.region,drop_first=True,dtype=float); m=sm.OLS(z.species_richness,sm.add_constant(pd.concat([z[[x]],s],axis=1))).fit(); print(x,round(m.params[x],3),round(m.pvalues[x],6))

